(window.LP_CLIPS=window.LP_CLIPS||{});window.LP_CLIPS["zh"]=Object.assign(window.LP_CLIPS["zh"]||{},{"皮普和安全过街": "", "浣熊皮普在一个小镇里醒来，早晨阳光明亮。": "", "皮普想去看小狗，小狗在马路对面等着。": "", "可是马路很吵，汽车开得很快，皮普、小猫和小鸭子都太小了，过不去。": "", "皮普坐下来想了想。马路是人修的，所以人可以改变它。": "", "于是皮普去敲邻居的门，大家都走出来听。": "", "大家一起请求修一个安全过街的地方，小镇说好。": "", "挖掘机来了，压路机开过，工人们画上了明亮的条纹。": "", "现在汽车都停下来，大家一起过马路。": "", "皮普抱住了小狗。一个小小的声音和几个好朋友，改变了这条街。": "", "世界是人创造的，人也能让它变得更温柔。晚安，皮普。大家晚安。": ""});
